import React, { useState, useEffect } from 'react';
import '../Estilos/TuReservacion.css';

const ErrorNotification = ({ children }) => {
  return <div className="error-notification">{children}</div>;
};

function TuReservacion() {
  const [reservas, setReservas] = useState([]);
  const [error, setError] = useState(null);
  const [cargando, setCargando] = useState(true);

  useEffect(() => {
    const fetchReservas = async () => {
      setCargando(true);
      const token = localStorage.getItem('token');
      if (!token) {
        setError('No se encontró el token de autenticación.');
        setCargando(false);
        return;
      }

      try {
        const response = await fetch('http://localhost:5000/api/reservas', {
          method: 'GET',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });

        if (response.ok) {
          const data = await response.json();
          setReservas(data.reservas || []);
        } else {
          const errorData = await response.json();
          setError(errorData.error || 'Error al obtener las reservas.');
        }
      } catch (error) {
        console.error('Error de red:', error);
        setError('Error al conectar con el servidor.');
      } finally {
        setCargando(false);
      }
    };

    fetchReservas();
  }, []);

  // Función para manejar la eliminación de una reserva
  const desagendarReserva = async (id) => {
    const token = localStorage.getItem('token');
    if (!token) {
      setError('No se encontró el token de autenticación.');
      return;
    }

    try {
      const response = await fetch(`http://localhost:5000/api/reservas/${id}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
      });

      if (response.ok) {
        // Actualizar la lista de reservas eliminando la reserva desagendada
        setReservas((prevReservas) => prevReservas.filter((reserva) => reserva._id !== id));
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Error al desagendar la reserva.');
      }
    } catch (error) {
      console.error('Error de red:', error);
      setError('Error al conectar con el servidor.');
    }
  };

  return (
    <main id="tu-reservacion">
      <div className="contenedor">
        <h2>Tu Reservación</h2>
        {cargando && <p>Cargando reservas...</p>}
        {error && <ErrorNotification>{error}</ErrorNotification>}

        {reservas.length > 0 ? (
          <div className="reservacion">
            {reservas.map((reserva) => (
              <div className="tarjeta" key={reserva._id}>
                <div className="detalle">
                  <strong>Día:</strong> {reserva.fecha}
                  <br />
                  <strong>Hora:</strong> {reserva.hora}
                  <br />
                  <strong>Cancha:</strong> {reserva.cancha}
                  <br />
                  <strong>Equipo:</strong> {reserva.equipo}
                  <br />
                  <button
                    className="btn-desagendar"
                    onClick={() => desagendarReserva(reserva._id)}
                  >
                    Desagendar
                  </button>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <p>No hay reservas realizadas.</p>
        )}
      </div>
    </main>
  );
}

export default TuReservacion;
